function icon(name){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('class','ui-icon');svg.setAttribute('aria-hidden','true');svg.setAttribute('focusable','false');svg.setAttribute('fill','none');svg.setAttribute('stroke','currentColor');svg.setAttribute('stroke-width','1.7');svg.setAttribute('stroke-linecap','round');svg.setAttribute('stroke-linejoin','round');const path=document.createElementNS(svg.namespaceURI,'path');path.setAttribute('d',iconPaths[name]||iconPaths.arrow);svg.append(path);return svg;}
function decorateControls(){for(const b of document.querySelectorAll('nav button')){if(!b.querySelector('svg'))b.prepend(icon({pipeline:'grid',discovery:'search',outbox:'mail',settings:'sliders'}[b.dataset.view]));}const names={'find-companies':'search','target-dubai':'globe','automatic-research':'spark','target-copy':'copy','target-import':'download','sync':'refresh','copy-prompt':'copy','starter':'spark','discover':'search','retry-workspace':'refresh','pause':state?.paused?'play':'pause'};for(const [id,name] of Object.entries(names)){const b=$(id);if(b&&!b.hasAttribute('aria-busy')&&!b.querySelector('svg'))b.prepend(icon(name));}for(const b of document.querySelectorAll('.row-open')){if(!b.querySelector('svg'))b.append(icon('arrow'));}}
function setWorkspaceReady(){if(workspaceReady)return;workspaceReady=true;document.body.classList.remove('is-loading');$('workspace-loader').hidden=true;$('workspace-loader').setAttribute('aria-busy','false');for(const b of document.querySelectorAll('nav button'))b.disabled=false;$('pause').disabled=false;for(const b of document.querySelectorAll('[data-flow]'))b.disabled=false;}
function filterIndustries(){const query=$('industry-search').value.trim().toLowerCase();let count=0;for(const group of $('industry-choices').children){let visible=0;for(const label of group.querySelectorAll('.industry-option')){const match=(label.textContent+' '+group.querySelector('h3').textContent).toLowerCase().includes(query);label.hidden=!match;if(match){count++;visible++;}}group.hidden=visible===0;}$('industry-search-results').textContent=query?(count?count+(count===1?' matching industry.':' matching industries.')+' Your other selections are kept.':'No industries match. Try a broader term.'):'';}

function notice(text,error=false){const box=$('notice');box.replaceChildren(node('span',text));box.classList.toggle('error',error);const close=node('button','×','notice-dismiss');close.type='button';close.setAttribute('aria-label','Dismiss notification');close.onclick=()=>{box.hidden=true;};box.append(close);box.hidden=false;if($('detail').open){$('dialog-feedback').textContent=text;$('dialog-feedback').classList.toggle('error',error);}}
function fieldError(id,text,field){const box=$(id);box.textContent=text;box.hidden=!text;if(field){field.setAttribute('aria-invalid',String(Boolean(text)));field.setAttribute('aria-describedby',[...new Set((field.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean).concat(id))].join(' '));if(text)field.focus();}}
function errorText(error){if(error instanceof SyntaxError)return 'This is not valid JSON. Copy the complete JSON response from ChatGPT, without code fences, and try again.';if(error.name==='AbortError')return 'The local request timed out. Check the activity list before retrying.';if(error instanceof TypeError)return 'Could not reach the local app. Check that its dashboard is running, then retry.';return error.message||'Something went wrong. Please try again.';}
async function pending(button,label,task){if(button.disabled)return;const content=Array.from(button.childNodes);button.disabled=true;button.setAttribute('aria-busy','true');button.replaceChildren(node('span',undefined,'spinner'),document.createTextNode(label));try{return await task();}finally{button.replaceChildren(...content);button.disabled=false;button.removeAttribute('aria-busy');if(state&&['starter','discover','sync'].includes(button.id))button.disabled=state.busy||state.paused;if(state&&button.id==='automatic-research')renderAutomatic();if(state&&button.id==='campaign-close')renderCampaign();if(button.id==='approve-review')button.disabled=!!button.dataset.approved||!selected?.review?.can_approve;decorateControls();}}

function safeLink(url,label){try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)return node('span','Source URL unavailable');const a=node('a',label||u.hostname);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label',(label||u.hostname)+' (opens in a new tab)');return a;}catch{return node('span','Source URL unavailable');}}
async function api(path,data,timeout=15000){const options={credentials:'same-origin',cache:'no-store'};if(data!==undefined){options.method='POST';options.headers={'Content-Type':'application/json','X-CSRF-Token':state.csrf};options.body=JSON.stringify(data);}const controller=new AbortController();options.signal=controller.signal;const timer=setTimeout(()=>controller.abort(),timeout);try{const r=await fetch(path,options);const value=await r.json();if(!r.ok)throw Error(value.error||'Local request failed');return value;}finally{clearTimeout(timer);}}
async function action(kind,payload={}){try{const r=await api('/api/task',{kind,...payload});notice('Task queued. Follow its progress in Find clients → Session activity.');await refresh();return r;}catch(e){notice(errorText(e),true);return null;}}
function switchView(view){if(!['pipeline','discovery','outbox','settings'].includes(view))return;active=view;if(state){renderNextStep();renderFlowContext();}for(const e of document.querySelectorAll('.view'))e.hidden=e.id!==view;for(const b of document.querySelectorAll('nav button')){const current=b.dataset.view===view;b.classList.toggle('active',current);if(current)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');}$('crumb').textContent='WORKSPACE / '+({pipeline:'REVIEW & RESULTS',discovery:'FIND CLIENTS',outbox:'CAMPAIGN & DELIVERY',settings:'SETUP & PREFERENCES'})[view];const heading=$(view).querySelector('h1');heading.tabIndex=-1;heading.focus();window.scrollTo(0,0);try{sessionStorage.setItem('shine-active-view',view);}catch{}}
function pipeline(){
 const leads=state.leads.filter(l=>!l.is_demo);renderSessionFilter(leads);
 const counts=[['Drafts to review',leads.filter(l=>l.has_draft&&!terminalStatuses.includes(l.status)).length,'Open and check your next message'],['Needs research',leads.filter(l=>!l.has_draft&&!terminalStatuses.includes(l.status)).length,'More evidence or a draft is needed'],['Messages sent',leads.filter(l=>['Sent','Replied','Interview','Won'].includes(l.status)).length,'Jobs and client introductions'],['Prospective clients',leads.filter(l=>l.kind==='Cold Outreach'&&!closedStatuses.includes(l.status)).length,'Active business introductions']];
 clear($('metrics'));for(const [label,value,note]of counts){const c=node('button',undefined,'metric');c.type='button';c.setAttribute('aria-label',label+': '+value+'. Filter pipeline');c.onclick=()=>{$('pipeline-session').value='';$('search').value='';$('kind').value=label==='Prospective clients'?'Cold Outreach':'';$('status-filter').value=({'Drafts to review':'draft','Needs research':'research','Messages sent':'sent'})[label]||'active';pipeline();$('result-count').tabIndex=-1;$('result-count').focus();};c.append(node('span',label),node('strong',String(value)),node('small',note));$('metrics').append(c);}
 const query=$('search').value.trim().toLowerCase(),kind=$('kind').value,status=$('status-filter').value;
 const sessionFilter=$('pipeline-session').value;const visible=leads.filter(l=>(!sessionFilter||l.session_id===sessionFilter)&&(!kind||l.kind===kind)&&((l.company||'')+' '+(l.title||'')).toLowerCase().includes(query)&&(status==='all'||status==='sent'&&['Sent','Replied','Interview','Won'].includes(l.status)||status==='active'&&!closedStatuses.includes(l.status)||status==='closed'&&closedStatuses.includes(l.status)||status==='draft'&&l.has_draft&&!terminalStatuses.includes(l.status)||status==='research'&&!l.has_draft&&!terminalStatuses.includes(l.status)));
 clear($('leads'));for(const l of visible){const tr=node('tr'),company=node('td');company.append(node('strong',l.company||'Company unconfirmed'),node('small',l.title));tr.append(company,node('td',l.kind==='Cold Outreach'?'Prospective client':'Advertised job'),node('td',[l.location_city,l.country].filter(Boolean).join(', ')||'Location unverified'),node('td',l.score===undefined||l.score===null?'Not scored':String(l.score)+'/100','score'));const st=node('td');st.append(badge(l.status));tr.append(st);const more=node('td'),button=node('button','Review','row-open');button.setAttribute('aria-label','Review '+(l.company||l.title));button.onclick=()=>openLead(l.id);button.append(icon('arrow'));more.append(button);tr.append(more);for(const [i,cell]of Array.from(tr.cells).entries())cell.dataset.label=['Company / role','Opportunity','Market','Fit / 100','Status','Action'][i];$('leads').append(tr);}
 $('result-count').textContent=visible.length+' of '+leads.length+' opportunities · Fit is a screening score, not a prediction.';
 $('empty').hidden=visible.length>0;$('empty').textContent=sessionFilter&&!leads.some(l=>l.session_id===sessionFilter)?'This session has no saved results yet. Go to Find clients to research this audience, or choose All research sessions to see earlier work.':leads.length?'No matches for these filters. Try another search or choose Clear filters.':'No opportunities yet. Choose Find companies to start your first research session.';
}
function taskSummary(task){const r=task.result||{};if(task.status==='Running'||task.status==='Queued')return 'Working on this task. This page updates automatically.';if(r.error)return /worker is active/.test(r.error)?'Another worker is running. Stop it in its Terminal window, then retry this task.':r.error;const parts=[];if(r.new!==undefined)parts.push(r.new+(r.new===1?' company added':' companies added'));if(r.drafts!==undefined)parts.push(r.drafts+(r.drafts===1?' draft saved':' drafts saved'));if(r.duplicates)parts.push(r.duplicates+' existing records kept');if(r.synced!==undefined)parts.push(r.synced+' records synced');if(r.drafts_rejected)parts.push(r.drafts_rejected+' drafts need repair (companies kept)');if(r.errors?.length)parts.push(r.errors.length+(r.errors.length===1?' validation issue':' validation issues')+' — expand recovery steps');if(r.notion_sync)parts.push(r.notion_sync.errors?.length?'Notion sync needs attention':r.notion_sync.synced+' records synced to Notion');return parts.join(' · ')||'No additional result details.';}
let tasksSignature='';
function renderTasks(){renderNotionLink();const signature=JSON.stringify(state.tasks);if(signature!==tasksSignature){const opened=new Set(Array.from(document.querySelectorAll('[data-task-id] details[open]'),d=>d.closest('[data-task-id]').dataset.taskId+'|'+d.querySelector('summary').textContent));clear($('tasks'));clear($('past-tasks'));$('activity-history').hidden=state.tasks.length<2;$('activity-history-count').textContent='('+Math.max(0,state.tasks.length-1)+')';if(!state.tasks.length)$('tasks').append(node('p','No research activity yet. Create a prompt above to get started.','caption'));for(const [index,t] of state.tasks.entries()){const item=node('article',undefined,'task'),info=node('div');info.append(node('strong',({starter:'Research examples',discover:'Source discovery',sync:'Notion sync',import:'Research import','target-import':'Targeted research import','automatic-research':'Automatic research + drafts'})[t.kind]||t.kind),node('p',new Date(t.created_at).toLocaleString(),'caption'),node('p',taskSummary(t),'task-summary'+(['Failed','Needs attention'].includes(t.status)?' error':'')));item.dataset.taskId=t.id;if(t.result?.errors?.length){const issueDetails=node('details');issueDetails.append(node('summary','Issues and recovery steps'));const issues=node('ul',undefined,'import-issues');for(const e of t.result.errors){const li=node('li');li.append(node('strong',(e.company||e.source||'Candidate')+': '),document.createTextNode(e.company_saved?'Company saved; email draft withheld. '+e.error+'. Open the company review and use its drafting prompt to repair the draft.':e.error));issues.append(li);}issueDetails.append(issues);info.append(issueDetails);}if(Object.keys(t.result||{}).length){const details=node('details');details.append(node('summary','Technical details'),node('pre',JSON.stringify(t.result,null,2)));info.append(details);}item.append(info,badge(t.status));(index===0?$('tasks'):$('past-tasks')).append(item);for(const d of item.querySelectorAll('details'))d.open=opened.has(t.id+'|'+d.querySelector('summary').textContent);}tasksSignature=signature;}$('busy').replaceChildren(...(state.busy?[node('span',undefined,'spinner'),document.createTextNode('Research in progress…')]:[document.createTextNode('No task running')]));$('busy').setAttribute('role','status');for(const id of ['starter','discover','sync']){const b=$(id);b.disabled=state.busy||state.paused;b.title=state.paused?'Resume the agent before starting research.':state.busy?'Wait for the current task to finish.':'';}}
function renderOutbox(){clear($('readiness'));for(const reason of state.readiness.production_blockers)$('readiness').append(node('p',friendlyReviewMessage(reason),'caption'));if(!state.readiness.production_blockers.length)$('readiness').append(node('p','Configuration gates passed. Current source evidence is rechecked at dispatch.','caption'));clear($('outbox-rows'));for(const r of state.outbox){const tr=node('tr');tr.append(node('td',r.recipient),node('td',r.mode),node('td',r.stage?'Follow-up '+r.stage:'Initial'));const s=node('td');s.append(badge(r.state));tr.append(s,node('td',r.error||r.sent_at||r.due_at));$('outbox-rows').append(tr);}if(!state.outbox.length){const tr=node('tr'),td=node('td','No messages queued.');td.colSpan=5;tr.append(td);$('outbox-rows').append(tr);}clear($('gmail-status'));$('gmail-status').append(node('h2',state.readiness.checks.self_test_reply_verified?'Live self-inbox test verified':state.setup.gmail_token_present?'Gmail token found; live check required':'Gmail setup is pending'),node('p',state.readiness.checks.self_test_reply_verified?'Your saved test includes reply verification. Current sender policy and each message are still checked before sending.':state.setup.gmail_token_present?'Run the existing Gmail check and self-inbox test before approving production sending.':'No Gmail mailbox token was found in this installation. Use the Gmail setup guide, or update your already connected installation while preserving its state folder.'));clear($('suppressions'));for(const s of state.suppressions)$('suppressions').append(node('p',s.value+' · '+s.reason,'caption'));if(!state.suppressions.length)$('suppressions').append(node('p','No additional runtime suppressions. The configured company/domain exclusions still apply.','caption'));}
function renderPreferences(){const form=$('preferences');if(!preferencesDirty&&!form.contains(document.activeElement)){for(const key of ['title_keywords','required_skills_any','countries'])form.elements[key].value=(state.preferences[key]||[]).join('\n');form.elements.weekly_capacity_hours.value=state.preferences.weekly_capacity_hours||20;form.elements.max_post_age_days.value=state.preferences.max_post_age_days||60;}clear($('connections'));for(const [name,ready]of [['Local Gmail token',state.setup.gmail_token_present],['Local Notion key',state.setup.notion_key_present],['Optional search API key',state.setup.search_key_present],['AI drafting API setup',state.setup.ai_key_present]])$('connections').append(node('p',name+': '+(ready?'Present; live validation required':'Not configured'),'caption'));$('notion-status').textContent=state.setup.notion_key_present?'Notion setup found. The connection is checked when you sync.':'Notion sync is not set up in this local app. Follow the included setup guide to connect your tracker.';}
async function refresh(){if(refreshing)return;refreshing=true;try{state=await api('/api/state');const modeNames={'draft-only':'Drafts only',automatic:'Automatic mode configured',test:'Test mode configured'};$('mode').textContent=state.paused?'Agent paused':modeNames[state.sending.mode]||state.sending.mode;$('mode').classList.toggle('paused',state.paused);$('pause').textContent=state.paused?'Resume agent':'Pause agent';$('mode').title='Configured delivery policy; this indicator does not confirm that a delivery worker is running.';$('version').textContent='v'+state.version;$('connection-status').textContent=state.worker_running?'Connected locally · Run-Shine worker detected · Keep your Mac awake.':'Connected locally · Run-Shine worker not detected · Open Run-Shine.command to run scheduled delivery.';$('reconnect').hidden=true;renderNextStep();$('connection-status').classList.remove('offline');setWorkspaceReady();const signature=JSON.stringify(state.leads);if(signature!==renderedLeads){pipeline();renderedLeads=signature;}renderTasks();renderOutbox();renderCampaign();renderPreferences();renderTargetSessions();showTargetPrompt();renderAutomatic();renderFlowContext();decorateControls();}catch(e){if(!workspaceReady){$('loading-title').textContent='Unable to open your workspace';$('loading-description').textContent='Check that the local dashboard is running, then retry. Your saved records remain in the app.';$('workspace-loader').setAttribute('aria-busy','false');$('workspace-loader').classList.add('load-error');$('retry-workspace').hidden=false;} $('connection-status').textContent='Connection interrupted. Check that the dashboard is running. Retrying automatically…';$('connection-status').classList.add('offline');$('reconnect').hidden=false;}finally{refreshing=false;}}
async function openLead(id){const request=++leadRequest;if(!$('detail').open)draftOpener=document.activeElement;$('detail-content').hidden=true;$('lead-loader').hidden=false;$('detail-kind').textContent='OPPORTUNITY REVIEW';$('detail-company').textContent='Loading opportunity';if(!$('detail').open)$('detail').showModal();$('detail').setAttribute('aria-busy','true');try{const lead=await api('/api/lead?id='+encodeURIComponent(id),undefined,65000);if(request!==leadRequest||!$('detail').open)return;selected=lead;renderReview(lead.review);$('detail-kind').textContent=selected.kind==='Cold Outreach'?'PROSPECTIVE CLIENT · NO CONFIRMED VACANCY':'ADVERTISED OPPORTUNITY';$('detail-company').textContent=selected.company||'Company unconfirmed';$('detail-title').textContent=selected.title;setNotionLink($('detail-notion'),selected.notion_page_id);clear($('detail-facts'));for(const text of [selected.country||'Country unknown',selected.kind==='Cold Outreach'?'Client interest: unconfirmed':'Eligibility: '+(selected.remote_eligibility||'Not verified'),selected.status])$('detail-facts').append(badge(text));clear($('detail-reasons'));if(selected.draft_error)$('detail-reasons').append(node('li','Draft needs repair: '+selected.draft_error+'. Copy the drafting prompt below and use an exact quote from its cited source.'));for(const r of selected.reasons||[])$('detail-reasons').append(node('li',r));clear($('detail-links'));$('detail-links').append(safeLink(selected.url,'Original source'));clear($('detail-sources'));const sourceKeys=new Set();for(const d of [{url:selected.url,text:selected.source_text},...(selected.source_documents||[])].filter(d=>{const key=d.url+'|'+d.text;if(!d.text||sourceKeys.has(key))return false;sourceKeys.add(key);return true;})){const e=node('article',undefined,'source');e.append(safeLink(d.url,d.url),node('p',d.text));$('detail-sources').append(e);}$('detail-offer').textContent=selected.offer.scope+' '+selected.offer.reason;const draft=selected.draft||{subject:'',body:'',evidence:[]};$('draft-json').value=JSON.stringify({lead_id:selected.id,...draft},null,2);$('draft-form').querySelector('button').disabled=['Sending','Sent','Replied','Interview','Won','Closed','Do Not Contact','Rejected'].includes(selected.status);loadDraftFields();$('detail-content').hidden=false;$('lead-loader').hidden=true;$('detail').scrollTop=0;decorateControls();}catch(e){if(request===leadRequest){$('detail').close();notice(errorText(e),true);}}finally{if(request===leadRequest)$('detail').removeAttribute('aria-busy');}}
for(const b of document.querySelectorAll('nav button'))b.onclick=()=>switchView(b.dataset.view);
$('find-companies').onclick=()=>switchView('discovery');
$('pause').onclick=()=>pending($('pause'),'Updating…',async()=>{try{await api('/api/pause',{paused:!state.paused});await refresh();notice(state.paused?'Agent paused. Queued work will wait.':'Agent resumed under its existing delivery policy.');}catch(e){notice(errorText(e),true);}}).then(()=>{$('pause').textContent=state?.paused?'Resume agent':'Pause agent';decorateControls();});
for(const [id,kind] of [['starter','starter'],['discover','discover'],['sync','sync']])$(id).onclick=()=>pending($(id),'Starting…',async()=>{await action(kind);switchView('discovery');});
$('search').oninput=pipeline;$('kind').onchange=pipeline;$('status-filter').onchange=pipeline;$('pipeline-session').onchange=pipeline;
$('clear-filters').onclick=()=>{$('search').value='';$('kind').value='';$('status-filter').value='all';$('pipeline-session').value='';pipeline();$('search').focus();};
$('import').onchange=async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>240000)throw Error('Use a JSON file smaller than 240 KB.');const leads=JSON.parse(await file.text());await action('import',{leads});}catch(e){notice(errorText(e),true);}event.target.value='';};
function draftChanged(){return draftLoaded&&$('draft-json').value!==draftBaseline;}
function requestClose(){if(draftChanged()){$('discard-confirm').hidden=false;$('keep-editing').focus();return;}$('detail').close();}
$('close-detail').onclick=requestClose;$('cancel-draft').onclick=requestClose;
$('detail').addEventListener('cancel',event=>{event.preventDefault();requestClose();});
$('detail').addEventListener('close',()=>{leadRequest++;draftLoaded=false;draftOpener?.focus();});
$('keep-editing').onclick=()=>{$('discard-confirm').hidden=true;$('draft-body').focus();};
$('discard-draft').onclick=()=>{draftLoaded=false;$('detail').close();};
$('copy-prompt').onclick=async()=>{try{await navigator.clipboard.writeText(selected.prompt);notice('AI prompt copied. Paste it into your preferred AI conversation.');}catch{notice('Clipboard unavailable. Try selecting and copying the prompt in your research session.',true);}};
function loadDraftFields(){draftLoaded=false;const d=JSON.parse($('draft-json').value);$('draft-subject').value=d.subject||'';$('draft-body').value=d.body||'';draftBaseline=$('draft-json').value;draftLoaded=true;$('draft-error').hidden=true;$('discard-confirm').hidden=true;$('dialog-feedback').textContent='';const readOnly=terminalStatuses.includes(selected.status);$('draft-subject').readOnly=readOnly;$('draft-body').readOnly=readOnly;$('draft-json').readOnly=readOnly;updateWordCount();}
function updateWordCount(){const n=$('draft-body').value.trim().split(/\s+/).filter(Boolean).length;$('draft-word-count').textContent=n+' words · Research drafts aim for 100–150 words. Keep the exact portfolio URL.';}
function updateDraftJSON(){try{const d=JSON.parse($('draft-json').value);d.subject=$('draft-subject').value;d.body=$('draft-body').value;$('draft-json').value=JSON.stringify(d,null,2);fieldError('draft-error','',$('draft-json'));}catch{fieldError('draft-error','Fix the advanced JSON before editing the subject or message.',$('draft-json'));}updateWordCount();}
$('draft-subject').oninput=updateDraftJSON;$('draft-body').oninput=updateDraftJSON;
$('draft-json').oninput=()=>{try{const d=JSON.parse($('draft-json').value);$('draft-subject').value=d.subject||'';$('draft-body').value=d.body||'';updateWordCount();}catch{}};
$('draft-form').onsubmit=async event=>{event.preventDefault();const b=event.target.querySelector('button[type=submit]');await pending(b,'Saving draft…',async()=>{try{const draft=JSON.parse($('draft-json').value);if(draft.lead_id!==selected.id)throw Error('This draft belongs to a different opportunity. Reopen the correct company.');const r=await api('/api/draft',draft);draftLoaded=false;await refresh();await openLead(selected.id);notice(r.message);$('review-heading').tabIndex=-1;$('review-heading').focus();}catch(e){fieldError('draft-error',errorText(e));}});};
$('preferences').addEventListener('input',()=>{preferencesDirty=true;$('preferences-dirty').textContent='Unsaved changes';});
$('reset-preferences').onclick=()=>{preferencesDirty=false;$('preferences-dirty').textContent='';$('preferences-error').hidden=true;$('reset-preferences').blur();renderPreferences();};
$('preferences').onsubmit=async event=>{event.preventDefault();const f=event.target,payload={};for(const key of ['title_keywords','required_skills_any','countries'])payload[key]=f.elements[key].value.split('\n').map(s=>s.trim()).filter(Boolean);payload.weekly_capacity_hours=Number(f.elements.weekly_capacity_hours.value);payload.max_post_age_days=Number(f.elements.max_post_age_days.value);await pending(f.querySelector('button[type=submit]'),'Saving…',async()=>{try{const r=await api('/api/preferences',payload);preferencesDirty=false;$('preferences-dirty').textContent='Saved';fieldError('preferences-error','');notice(r.message);await refresh();}catch(e){fieldError('preferences-error',errorText(e));}});};
window.addEventListener('beforeunload',event=>{if(preferencesDirty||campaignDirty||draftChanged()||$('target-json').value.trim()){event.preventDefault();event.returnValue='';}});
function renderTargetSessions(){
 renderSessionFilter(state.leads.filter(l=>!l.is_demo));
 const countries=state.preferences.countries||[];
 if(JSON.stringify(Array.from($('target-country').options,o=>o.value))!==JSON.stringify(countries)){const selectedCountry=$('target-country').value;clear($('target-country'));for(const name of countries){const option=node('option',name);option.value=name;$('target-country').append(option);}if(countries.includes(selectedCountry))$('target-country').value=selectedCountry;}
 $('target-dubai').disabled=!countries.includes('United Arab Emirates');
 $('target-dubai').title=$('target-dubai').disabled?'Add United Arab Emirates to your countries in Preferences to use this shortcut.':'';
 if(!$('target-industries').options.length){const groups={};for(const [key,value] of Object.entries(state.industries||{})){if(!groups[value.group]){groups[value.group]=node('optgroup');groups[value.group].label=value.group;$('target-industries').append(groups[value.group]);}const option=node('option',value.name);option.value=key;groups[value.group].append(option);}}
 const sessions=state.target_sessions||[],signature=JSON.stringify(sessions);
 if(signature!==targetSessionsSignature){clear($('target-saved'));for(const s of sessions){const option=node('option',s.spec.city+' · '+s.spec.company_type+' · '+new Date(s.created_at).toLocaleString());option.value=s.id;$('target-saved').append(option);}targetSessionsSignature=signature;if(!sessions.some(s=>s.id===targetSessionId))targetSessionId=sessions[0]?.id||'';$('target-saved').value=targetSessionId;showTargetPrompt();}
 $('target-industries').required=false;
 renderIndustries();renderImportPreview();$('research-step').hidden=!targetSessionId;$('import-step').hidden=!targetSessionId;$('target-copy').disabled=!targetSessionId;
}
function showTargetPrompt(){const s=(state.target_sessions||[]).find(s=>s.id===targetSessionId);$('target-prompt').value=s?.prompt||'';$('session-summary').textContent=s?[s.spec.city,s.spec.country,s.spec.company_type,(s.spec.industries||[]).map(k=>state.industries[k]?.name||k).join(', '),'Up to '+s.spec.limit+' companies'].filter(Boolean).join(' · '):'Create your first research prompt above.';}
function renderIndustries(){if(!$('industry-choices').children.length){const groups={};for(const option of $('target-industries').options){const groupName=option.parentElement.label||'Industries';if(!groups[groupName]){const group=node('section',undefined,'industry-group');group.append(node('h3',groupName));const list=node('div',undefined,'industry-options');group.append(list);$('industry-choices').append(group);groups[groupName]=list;}const label=node('label',undefined,'industry-option'),input=node('input');input.type='checkbox';input.value=option.value;input.checked=option.selected;input.onchange=()=>{option.selected=input.checked;updateIndustryCount();};label.append(input,node('span',option.textContent));groups[groupName].append(label);}}updateIndustryCount();}
function updateIndustryCount(){const n=$('target-industries').selectedOptions.length;$('industry-count').textContent='('+n+' selected)';$('industry-help').textContent=$('target-type').value==='Brand'?'Choose at least one industry. You can select more than one.':'Optional. For agencies, these describe their clients and require source evidence.';}
$('target-type').onchange=updateIndustryCount;
$('target-dubai').onclick=()=>{$('target-country').value='United Arab Emirates';$('target-city').value='Dubai';notice('Location set to Dubai, United Arab Emirates.');$('target-type').focus();};
$('target-saved').onchange=()=>{if($('target-json').value.trim()){notice('Research text is still in the import field. Check that it matches the selected session.');}targetSessionId=$('target-saved').value;showTargetPrompt();renderImportPreview();renderAutomatic();};
$('target-session').onsubmit=async event=>{event.preventDefault();const industries=Array.from($('target-industries').selectedOptions,o=>o.value);if($('target-type').value==='Brand'&&!industries.length){fieldError('target-error','Choose at least one industry for a brand search.');const firstGroup=$('industry-choices').querySelector('details');if(firstGroup){firstGroup.open=true;firstGroup.querySelector('input')?.focus();}return;}await pending(event.target.querySelector('button[type=submit]'),'Creating prompt…',async()=>{try{fieldError('target-error','');const result=await api('/api/target-session',{country:$('target-country').value,city:$('target-city').value.trim(),company_type:$('target-type').value,kind:$('target-kind').value,industries,limit:Number($('target-limit').value),campaign_target:$('audience-campaign-target').value?Number($('audience-campaign-target').value):null});targetSessionId=result.id;await refresh();showTargetPrompt();notice('Discovery session ready. Choose automatic research, or use the manual prompt.');if(!$('automatic-research').disabled)$('automatic-research').focus();else{$('automatic-setup').tabIndex=-1;$('automatic-setup').focus();}}catch(e){fieldError('target-error',errorText(e));}});};
$('target-copy').onclick=()=>pending($('target-copy'),'Copying…',async()=>{try{if(!$('target-prompt').value)throw Error('Create or choose a discovery session first.');await navigator.clipboard.writeText($('target-prompt').value);notice('Prompt copied. Paste it into ChatGPT with web search, then bring back its JSON response.');}catch(e){$('target-prompt').closest('details').open=true;$('target-prompt').focus();$('target-prompt').select();notice('Copy is unavailable. The prompt is selected; use Command+C or Ctrl+C.',true);}});
function parseResearch(){const raw=$('target-json').value;if(new TextEncoder().encode(raw).length>240000)throw Error('Use a research response smaller than 240 KB. Split larger results into separate sessions.');const value=JSON.parse(raw);if(!value||!Array.isArray(value.leads))throw Error('Expected a JSON object containing a leads array. Copy the complete response from ChatGPT.');if(value.leads.length>20||value.leads.some(l=>!l||typeof l!=='object'||Array.isArray(l)||typeof l.company!=='string'||!l.company.trim()))throw Error('Use at most 20 company objects, each with a company name.');const session=(state.target_sessions||[]).find(s=>s.id===targetSessionId);if(session&&value.leads.length>session.spec.limit)throw Error('This response exceeds the selected session’s candidate limit. Check the matching session.');return value;}
function renderImportPreview(){let valid=false;const raw=$('target-json').value.trim();$('target-json').setAttribute('aria-invalid','false');if(!raw){$('import-preview').textContent='Paste a research response to preview it here.';$('import-error').hidden=true;}else{try{const value=parseResearch();const names=value.leads.map(l=>l.company);$('import-preview').textContent=names.length?names.length+(names.length===1?' company ready for validation: ':' companies ready for validation: ')+names.join(', '):'No matching companies were returned. Try adjusting your audience and creating a new research prompt.';valid=names.length>0;$('import-error').hidden=true;}catch(e){$('import-preview').textContent='The response needs a correction before import.';fieldError('import-error',errorText(e));$('target-json').setAttribute('aria-invalid','true');}}$('target-import').disabled=!valid||!targetSessionId||state.busy||state.paused||importing;$('target-import').title=state.paused?'Resume the agent before importing.':state.busy?'Wait for the current task to finish.':!valid?'Paste a valid research response first.':'';}
$('industry-search').oninput=filterIndustries;
$('retry-workspace').onclick=()=>pending($('retry-workspace'),'Reconnecting…',refresh);
$('target-json').oninput=renderImportPreview;
$('target-import').onclick=async()=>{if(importing)return;try{const value=parseResearch();if(!targetSessionId)throw Error('Choose the matching research session first.');importing=true;renderImportPreview();$('target-import').setAttribute('aria-busy','true');$('target-import').replaceChildren(node('span',undefined,'spinner'),document.createTextNode('Queueing import…'));const r=await action('target-import',{session_id:targetSessionId,leads:value.leads});if(r){notice('Import queued. Your research text is kept here. Check Session activity for completion or validation errors before importing again.');}}catch(e){fieldError('import-error',errorText(e));}finally{importing=false;$('target-import').removeAttribute('aria-busy');$('target-import').textContent='Import companies + drafts';renderImportPreview();decorateControls();}};
document.querySelector('nav button[data-view=pipeline]').setAttribute('aria-current','page');
try{const saved=sessionStorage.getItem('shine-active-view');if(saved&&saved!=='pipeline')switchView(saved);}catch{}
for(const b of document.querySelectorAll('nav button'))b.disabled=true;$('pause').disabled=true;decorateControls();
