/* v0.10: audience controls remain usable by keyboard and survive a page reload. */
const citySuggestions={'United States':['New York','Los Angeles','Chicago','San Francisco','Austin'],'United Kingdom':['London','Manchester','Bristol'],'United Arab Emirates':['Dubai','Abu Dhabi','Sharjah'],'Australia':['Sydney','Melbourne','Brisbane','Perth'],'New Zealand':['Auckland','Wellington'],'Germany':['Berlin','Munich'],'France':['Paris'],'Netherlands':['Amsterdam']};
let audienceRestored=false;
function locationError(){const city=$('target-city').value.trim().toLowerCase().replaceAll(' ',''),country=$('target-country').value;return ['dubai','abudhabi','sharjah'].includes(city)&&country!=='United Arab Emirates'?'Choose United Arab Emirates for this city, or enter a city in '+country+'.':'';}
function updateAudience(save=true){
 const message=locationError();$('location-error').textContent=message;$('location-error').hidden=!message;$('target-city').setAttribute('aria-invalid',String(Boolean(message)));
 const button=$('target-session').querySelector('button[type=submit]');if(!button.hasAttribute('aria-busy'))button.disabled=Boolean(message);
 const count=$('target-industries').selectedOptions.length,city=$('target-city').value.trim();
 const summary=[city?city+', '+$('target-country').value:'Choose a city',$('target-type').value,count+' '+(count===1?'industry':'industries'),'Up to '+$('target-limit').value+' companies'].join(' · ');
 if($('audience-summary').textContent!==summary)$('audience-summary').textContent=summary;
 if(state)renderAutomatic();
 if(save)try{sessionStorage.setItem('shine-audience-v1',JSON.stringify({country:$('target-country').value,city:$('target-city').value,company_type:$('target-type').value,kind:$('target-kind').value,limit:$('target-limit').value,industries:Array.from($('target-industries').selectedOptions,o=>o.value)}));}catch{}
}
function updateCities(){clear($('city-suggestions'));for(const city of citySuggestions[$('target-country').value]||[]){const option=node('option');option.value=city;$('city-suggestions').append(option);}}
let selectedIndustriesSignature='';
function renderSelectedIndustries(){const parent=$('selected-industries');const selectedOptions=Array.from($('target-industries').selectedOptions);const signature=selectedOptions.map(o=>o.value).join('|');if(signature===selectedIndustriesSignature){$('clear-industries').disabled=!selectedOptions.length;return;}selectedIndustriesSignature=signature;clear(parent);for(const option of selectedOptions){const chip=node('button',option.textContent+' ×','selection-chip');chip.type='button';chip.setAttribute('aria-label','Remove '+option.textContent);chip.onclick=()=>{option.selected=false;const check=Array.from($('industry-choices').querySelectorAll('input')).find(e=>e.value===option.value);if(check)check.checked=false;updateIndustryCount();updateAudience();$('industry-search').focus();};parent.append(chip);}$('clear-industries').disabled=!selectedOptions.length;}
renderIndustries=function(){
 if(!$('industry-choices').children.length){const groups={};for(const option of $('target-industries').options){const name=option.parentElement.label||'Industries';if(!groups[name]){const group=node('details',undefined,'industry-group');group.dataset.group=name;group.open=false;const summary=node('summary',name);const list=node('div',undefined,'industry-options');group.append(summary,list);$('industry-choices').append(group);groups[name]=list;}const label=node('label',undefined,'industry-option'),input=node('input');input.type='checkbox';input.value=option.value;input.checked=option.selected;input.onchange=()=>{option.selected=input.checked;updateIndustryCount();};label.append(input,node('span',option.textContent));groups[name].append(label);}}
 if(!audienceRestored){audienceRestored=true;try{const saved=JSON.parse(sessionStorage.getItem('shine-audience-v1')||'null');if(saved){if(Array.from($('target-country').options).some(o=>o.value===saved.country))$('target-country').value=saved.country;$('target-city').value=String(saved.city||'').slice(0,80);if(['Brand','Agency','Start-up'].includes(saved.company_type))$('target-type').value=saved.company_type;if(['Cold Outreach','Posted Job'].includes(saved.kind))$('target-kind').value=saved.kind;$('target-limit').value=Math.max(1,Math.min(10,Number(saved.limit)||5));for(const option of $('target-industries').options)option.selected=(saved.industries||[]).includes(option.value);for(const input of $('industry-choices').querySelectorAll('input'))input.checked=(saved.industries||[]).includes(input.value);}}catch{}updateCities();}
 updateIndustryCount();
};
const previousIndustryCount=updateIndustryCount;
updateIndustryCount=function(){previousIndustryCount();renderSelectedIndustries();updateAudience(false);for(const group of $('industry-choices').children){const n=group.querySelectorAll('input:checked').length;const text=group.dataset.group+(n?' · '+n+' selected':'');if(group.querySelector('summary').textContent!==text)group.querySelector('summary').textContent=text;}};
filterIndustries=function(){const query=$('industry-search').value.trim().toLowerCase();let count=0;for(const group of $('industry-choices').children){let visible=0;for(const label of group.querySelectorAll('.industry-option')){const match=(label.textContent+' '+group.dataset.group).toLowerCase().includes(query);label.hidden=!match;if(match){count++;visible++;}}group.hidden=visible===0;if(query){if(!group.dataset.searchOpen)group.dataset.searchOpen=String(group.open);group.open=true;}else if(group.dataset.searchOpen){group.open=group.dataset.searchOpen==='true';delete group.dataset.searchOpen;}}const text=query?(count?count+' matching '+(count===1?'industry':'industries')+'. Selected choices are kept.':'No matching industry. Try a broader word.') :'';if($('industry-search-results').textContent!==text)$('industry-search-results').textContent=text;};
$('industry-search').oninput=filterIndustries;
$('target-type').onchange=()=>{updateIndustryCount();updateAudience();};
$('target-country').onchange=()=>{updateCities();updateAudience();};
$('target-city').oninput=()=>updateAudience();$('target-kind').onchange=()=>updateAudience();$('target-limit').oninput=()=>updateAudience();
$('industry-choices').addEventListener('change',()=>updateAudience());
$('clear-industries').onclick=()=>{for(const option of $('target-industries').options)option.selected=false;for(const input of $('industry-choices').querySelectorAll('input'))input.checked=false;updateIndustryCount();updateAudience();$('industry-search').focus();};
function presetLocation(country,city){if(!Array.from($('target-country').options).some(o=>o.value===country)){notice('Add '+country+' to your country preferences before choosing this location.',true);return;}$('target-country').value=country;$('target-city').value=city;updateCities();updateAudience();notice('Location selected: '+city+', '+country+'.');$('target-type').focus();}
$('target-dubai').onclick=()=>presetLocation('United Arab Emirates','Dubai');$('target-newyork').onclick=()=>presetLocation('United States','New York');$('target-london').onclick=()=>presetLocation('United Kingdom','London');
const oldShowTargetPrompt=showTargetPrompt;
showTargetPrompt=function(){oldShowTargetPrompt();const session=(state.target_sessions||[]).find(s=>s.id===targetSessionId);const steps=$('research-journey').children;const current=session?.automatic_result||session?.result?2:session?1:0;for(let i=0;i<steps.length;i++){steps[i].classList.toggle('is-current',i===current);if(i===current)steps[i].setAttribute('aria-current','step');else steps[i].removeAttribute('aria-current');}};
if(location.protocol==='file:'){$('environment-banner').classList.add('preview');$('environment-banner').replaceChildren(node('strong','DESIGN PREVIEW — SAMPLE DATA'),node('span','Nothing is saved or sent. Open the live app from Start-Agent.command for real research prompts.'));}

// One explicit decision replaces separate per-field approval switches.
function renderReview(review){
 delete $('approve-review').dataset.approved;const r=review||{blockers:['Review details unavailable. Reopen this company.']};
 $('review-schedule').textContent=r.schedule||'Sending stays within your configured rules.';
 clear($('review-facts'));
 for(const text of ['Recipient: '+(r.recipient||'needs a published source'),'Fit: '+(r.score??'?')+'/100','Timezone: '+(r.time_zone||'needs verification')])$('review-facts').append(badge(text));
 if(r.next_window){const p=node('span','Next window opens: '+new Date(r.next_window).toLocaleString([], {timeZone:r.time_zone||'UTC',weekday:'short',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}),'caption');$('review-facts').append(p);}
 if(r.contact_source)$('review-facts').append(safeLink(r.contact_source,'Contact source'));
 if(r.timezone_source)$('review-facts').append(safeLink(r.timezone_source,'Location source'));
 clear($('review-blockers'));for(const text of r.blockers||[])$('review-blockers').append(node('li',friendlyReviewMessage(text)));
 $('review-setup').textContent=(r.setup_blockers||[]).length?'Sender setup still needed: '+r.setup_blockers.map(friendlyReviewMessage).join(' · '):'Delivery requires the agent running on your Mac. Daily limits and reply stop rules remain active.';
 $('review-attestation').textContent=r.attestation||'';
 $('approve-review').disabled=!r.can_approve;$('approve-review').title=r.can_approve?'Confirm the displayed recipient, message and outreach review.':'Resolve the listed research issues first.';
 $('review-feedback').textContent=r.already_approved?'Already approved. The sender will process it when setup and delivery conditions are satisfied.':'';
}
$('approve-review').onclick=()=>pending($('approve-review'),'Approving…',async()=>{
 if(draftChanged()){$('review-feedback').textContent='Save your edited draft first, then reopen this review.';return;}
 try{const result=await api('/api/review-approve',{lead_id:selected.id,token:selected.review.token,reviewed:true});$('review-feedback').textContent=result.message;$('approve-review').dataset.approved='true';$('approve-review').disabled=true;notice(result.message);await refresh();}
 catch(e){$('review-feedback').textContent=errorText(e);}
});

function friendlyReviewMessage(text){
 if(/policy hash/.test(text))return 'Review and approve your current sending setup once. Ordinary discovery sessions do not need this again.';
 if(/Missing exact location evidence/.test(text))return 'Add an official source that confirms the company’s office city.';
 if(/Missing exact industry evidence/.test(text))return 'Add official source text confirming the selected industry.';
 if(/Missing exact company_type evidence/.test(text))return 'Add official source text confirming the company type.';
 return text.replaceAll('Delivery queue','Campaign & delivery');
}

function renderAutomatic(){
 const s=(state.target_sessions||[]).find(s=>s.id===targetSessionId), b=$('automatic-research');
 const ready=state.setup.openai_key_present&&state.setup.search_key_present;
 b.disabled=!s||!ready||state.busy||state.paused||s.spec.limit>10||Boolean(s.automatic_result);
 $('automatic-setup').textContent=!ready?'Setup needed: run Configure-Automatic-Research.command in your existing installation, then restart the workspace. Keys stay on your Mac.':s?.spec.limit>10?'Choose a maximum of 10 candidates for the automatic pilot.':s?.automatic_result?'This session has finished. Review its results below; create a new session to research again.':'API keys found; live access will be checked when you start. Manual prompt and JSON import remain available below.';
 const task=state.tasks.find(t=>t.kind==='automatic-research'&&t.result?.session_id===s?.id);const r=task?.result||s?.automatic_result;
 renderAudienceMatch();
 const u=r?.usage, month=state.automatic;
 $('automatic-progress').textContent=r?[r.stage||'Session results', (r.researched||0)+' candidates researched', (r.new||0)+' saved', (r.drafts||0)+' drafts', u?'AI allowance reserved: $'+Number(u.reserved_usd).toFixed(4):'',u?'Reported token cost estimate: $'+Number(u.reported_usd_estimate).toFixed(4):'',r.message||''].filter(Boolean).join(' · '):month?'This month: $'+Number(month.reserved_usd).toFixed(4)+' AI allowance reserved · '+month.search_credits_reserved+' search credits reserved.':'';
}
$('automatic-research').onclick=()=>pending($('automatic-research'),'Starting research…',async()=>{try{const r=await action('automatic-research',{session_id:targetSessionId});if(r)notice('Automatic research started. Keep the app and Mac awake. Progress appears below; Pause agent stops new requests.');}catch(e){notice(errorText(e),true);}finally{renderAutomatic();}});

let campaignSelectionId=null, campaignDirty=false;
function renderCampaign(){
 const c=state.campaign,s=state.sending;
 $('campaign-signature').textContent=state.profile.email_signature||'No closing configured.';
 $('campaign-policy').textContent='Daily ceiling: '+s.daily_limit+' · '+(s.send_hours||[]).map(h=>String(h).padStart(2,'0')+':00').join('–')+' · '+(s.schedule_basis==='company'?'company-local time':'sender time')+' · weekdays · '+Math.round(s.minimum_interval_seconds/60)+' minute spacing.';
 if(!campaignDirty&&campaignSelectionId!==(c?.id||'')){
  campaignSelectionId=c?.id||'';const n=c?.target||20;
  $('campaign-preset').value=[20,30,50].includes(n)?String(n):'custom';$('campaign-custom').value=n;
 }
 const custom=$('campaign-preset').value==='custom';
 $('campaign-custom-label').hidden=!custom;$('campaign-custom').disabled=!custom;$('campaign-custom').required=custom;
 $('campaign-meter').hidden=!c;$('campaign-meter').max=c?.target||1;$('campaign-meter').value=c?.attempted||0;$('campaign-progress').textContent=c?c.sent+' sent · '+c.attempted+' attempts reserved of '+c.target+' · '+c.remaining+' remaining · '+c.queued+' queued'+(c.remaining===0?' · Target reached; further sending is held.':''):'No active campaign. Choose a target; automatic sending stays held until a campaign is set.';
 $('campaign-save').textContent=c?'Update campaign target':'Set campaign target';
 $('campaign-close').disabled=!c||!$('campaign-close-confirm').checked||c.uncertain>0;
}
$('campaign-preset').onchange=()=>{campaignDirty=true;renderCampaign();};
$('campaign-custom').oninput=()=>{campaignDirty=true;};
$('campaign-close-confirm').onchange=renderCampaign;
$('campaign-form').onsubmit=async event=>{event.preventDefault();await pending($('campaign-save'),'Saving target…',async()=>{try{const target=Number($('campaign-preset').value==='custom'?$('campaign-custom').value:$('campaign-preset').value);const r=await api('/api/campaign',{action:state.campaign?'update':'start',target});campaignDirty=false;campaignSelectionId=null;fieldError('campaign-error','');notice(r.message);await refresh();}catch(e){fieldError('campaign-error',errorText(e));}});};
$('campaign-close').onclick=()=>pending($('campaign-close'),'Closing…',async()=>{try{if(!$('campaign-close-confirm').checked)return;const r=await api('/api/campaign',{action:'close'});$('campaign-close-confirm').checked=false;campaignDirty=false;campaignSelectionId=null;fieldError('campaign-error','');notice(r.message);await refresh();}catch(e){fieldError('campaign-error',errorText(e));}});

// Read-only setup guidance. These actions navigate; they never approve or send.
function renderNextStep(){
 const box=$('next-step'),button=$('next-step-action');box.hidden=active!=='pipeline';
 let title,description,label,view;
 if(state.paused){title='Your agent is paused';description='Research and queued sending will wait. Use Resume agent when you are ready.';label='Check campaign & delivery';view='outbox';}
 else if(!state.setup.openai_key_present||!state.setup.search_key_present){title='Connect automatic research';description='Add your OpenAI and Firecrawl API keys using Configure-Automatic-Research.command in this installation, then restart. Manual research is still available.';label='Check connections';view='settings';}
 else if(!state.preferences.title_keywords?.length||!state.preferences.required_skills_any?.length){title='Complete your targeting rules';description='Some title or skill rules are missing. Use editable email-design suggestions in Setup and preferences, then review and save.';label='Set targeting';view='settings';}
 else if(state.leads.some(l=>!l.is_demo&&l.has_draft&&!terminalStatuses.includes(l.status))){title='Your drafts are ready in Notion';description='Review the company, contact purpose and message in Notion, then set STATUS to Approve.';label='Review in Notion';view='pipeline';}
 else {title='Find your next freelance client';description='Choose a location and company type to start an on-demand research session.';label='Choose audience';view='discovery';}
 $('next-step-title').textContent=title;$('next-step-description').textContent=description;button.textContent=label;
 button.onclick=()=>{if(label==='Review in Notion'){const lead=state.leads.find(l=>l.notion_page_id&&l.has_draft&&!terminalStatuses.includes(l.status));if(lead){window.open('https://www.notion.so/'+lead.notion_page_id.replaceAll('-',''),'_blank','noopener,noreferrer');return;}}if(label==='Review drafts'){$('pipeline-session').value='';$('status-filter').value='draft';$('search').value='';$('kind').value='';pipeline();}switchView(view);};
}
$('reconnect').onclick=()=>pending($('reconnect'),'Reconnecting…',refresh);
$('review-results').onclick=()=>{$('pipeline-session').value=targetSessionId;$('status-filter').value='all';$('search').value='';$('kind').value='';pipeline();switchView('pipeline');};
document.addEventListener('keydown',event=>{if(event.key==='/'&&!event.metaKey&&!event.ctrlKey&&!event.altKey&&!$('detail').open&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!document.activeElement.isContentEditable){event.preventDefault();switchView('pipeline');$('search').focus();}});

// Navigation changes view only; all research and delivery retain explicit actions.
function audienceDiffers(session){
 if(!session)return false;
 const spec=session.spec;
 const normalized=value=>String(value||'').trim().toLowerCase();
 const industries=Array.from($('target-industries').selectedOptions,o=>o.value).sort();
 return normalized(spec.country)!==normalized($('target-country').value)||normalized(spec.city)!==normalized($('target-city').value)||spec.company_type!==$('target-type').value||spec.kind!==$('target-kind').value||Number(spec.limit)!==Number($('target-limit').value)||JSON.stringify([...(spec.industries||[])].sort())!==JSON.stringify(industries);
}
function renderAudienceMatch(){
 const session=(state.target_sessions||[]).find(s=>s.id===targetSessionId),changed=audienceDiffers(session);
 $('audience-change-notice').hidden=!changed;
 if(changed){$('automatic-research').disabled=true;$('automatic-setup').textContent='Audience changes are not saved to this session. Create a new discovery session, or choose Use this saved audience.';}
}
$('use-saved-audience').onclick=()=>{
 const session=(state.target_sessions||[]).find(s=>s.id===targetSessionId);if(!session)return;
 const s=session.spec;$('target-country').value=s.country;$('target-city').value=s.city;$('target-type').value=s.company_type;$('target-kind').value=s.kind;
 // Existing manual sessions may hold 11–20 candidates. Keep their exact audience.
 $('target-limit').max=Math.max(10,s.limit);$('target-limit').value=s.limit;
 for(const option of $('target-industries').options)option.selected=(s.industries||[]).includes(option.value);
 for(const input of $('industry-choices').querySelectorAll('input'))input.checked=(s.industries||[]).includes(input.value);
 updateCities();updateIndustryCount();updateAudience();renderAutomatic();notice('Saved audience restored. No research started.');$('research-heading').focus();
};
function renderFlowContext(){
 const missing=!state.preferences.title_keywords?.length||!state.preferences.required_skills_any?.length;
 $('targeting-missing').hidden=!missing;
 const blockers=state.readiness.production_blockers||[];
 $('delivery-state-explanation').textContent=state.paused?'The agent is paused. Queued messages wait until resumed.':!state.worker_running?'The Run-Shine worker is not detected. Open Run-Shine.command when you want scheduled processing; keep your Mac awake.':blockers.length?blockers.length+' setup or policy condition'+(blockers.length===1?' needs':'s need')+' attention. See Production readiness below.':'Run-Shine is detected. Each message must still pass approval, source, recipient, schedule, duplicate and reply checks.';
 for(const button of document.querySelectorAll('[data-flow]')){
  const current=active==='discovery'?(targetSessionId&&!audienceDiffers((state.target_sessions||[]).find(s=>s.id===targetSessionId))?'research':'audience'):active==='pipeline'?'review':active==='outbox'?'delivery':'';const here=button.dataset.flow===current;
  if(here)button.setAttribute('aria-current','location');else button.removeAttribute('aria-current');
 }
}
function openFlow(name){
 if(name==='audience'){switchView('discovery');$('target-country').focus();}
 else if(name==='research'){switchView('discovery');const heading=targetSessionId?$('research-heading'):$('target-session');heading.tabIndex=-1;heading.focus();heading.scrollIntoView({block:'start'});}
 else if(name==='review'){$('pipeline-session').value='';$('status-filter').value='draft';$('kind').value='';$('search').value='';pipeline();switchView('pipeline');}
 else switchView('outbox');
}
for(const button of document.querySelectorAll('[data-flow]'))button.onclick=()=>openFlow(button.dataset.flow);
$('delivery-check-setup').onclick=()=>switchView('settings');
$('suggest-targeting').onclick=()=>{
 const f=$('preferences');
 f.elements.title_keywords.value=['email designer','email marketing designer','Klaviyo designer','freelance email designer','email design'].join('\n');
 f.elements.required_skills_any.value=['Figma','Klaviyo','email design','email marketing'].join('\n');
 preferencesDirty=true;$('preferences-dirty').textContent='Suggested targeting added — review and save';
 f.elements.title_keywords.focus();notice('Suggestions filled in. Edit them and save when ready; no settings have been saved yet.');
};

function renderSessionFilter(leads){
 const control=$('pipeline-session'),current=control.value;
 const sessions=new Map((state.target_sessions||[]).map(s=>[s.id,s]));
 for(const lead of leads)if(lead.session_id&&!sessions.has(lead.session_id))sessions.set(lead.session_id,null);
 const options=[['','All research sessions'],...Array.from(sessions,([id,s])=>[id,s?[s.spec.city,s.spec.company_type,new Date(s.created_at).toLocaleDateString()].join(' · '):'Earlier session · '+id.slice(0,8)])];
 const signature=JSON.stringify(options);if(control.dataset.options===signature)return;
 control.dataset.options=signature;clear(control);for(const [value,label] of options){const option=node('option',label);option.value=value;control.append(option);}
 if(options.some(([id])=>id===current))control.value=current;
}

for(const link of document.querySelectorAll('.review-navigation a'))link.onclick=event=>{
 event.preventDefault();const target=document.querySelector(link.getAttribute('href'));if(!target)return;
 if(target.tagName==='SUMMARY')target.closest('details').open=true;
 target.tabIndex=-1;target.focus();target.scrollIntoView({block:'start'});
};

// v0.16: dashboard handles research; Notion owns final review and approval.
function setNotionLink(link,id){link.hidden=!id;if(id)link.href='https://www.notion.so/'+String(id).replaceAll('-','');else link.removeAttribute('href');}
function renderNotionLink(){if(state?.notion_database_url){const link=$('open-notion');link.hidden=false;link.href=state.notion_database_url;return;}const leads=(state?.leads||[]).filter(l=>l.notion_page_id&&(!targetSessionId||l.session_id===targetSessionId));setNotionLink($('open-notion'),leads[0]?.notion_page_id);}
